def _to_int(token):
    try:
        return int(token)
    except (TypeError, ValueError):
        return None


def answer(question):
    if not question.startswith("What is") or not question.endswith("?"):
        raise ValueError("unknown operation")
    body = question[len("What is"):-1].strip()
    if not body:
        raise ValueError("syntax error")
    body = body.replace("multiplied by", "multiplied_by").replace("divided by", "divided_by")
    tokens = [t.replace("_", " ") for t in body.split()]

    result = _to_int(tokens[0])
    if result is None:
        if tokens[0] in OPERATIONS:
            raise ValueError("syntax error")
        raise ValueError("unknown operation")
    i = 1
    while i < len(tokens):
        op = tokens[i]
        if op not in OPERATIONS:
            if _to_int(op) is not None:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")
        if i + 1 >= len(tokens):
            raise ValueError("syntax error")
        value = _to_int(tokens[i + 1])
        if value is None:
            if tokens[i + 1] in OPERATIONS:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")
        if op == "divided by" and value == 0:
            raise ValueError("syntax error")
        result = OPERATIONS[op](result, value)
        i += 2
    return result
